INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload) VALUES('core-2026-09-v3','punctuation-clauses','e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4','{"slug":"punctuation-clauses","title":"Punctuation, sentence boundaries and direct speech","level":"B1","order":57,"summary":"Use punctuation to show clause relationships, possession, quotation and sentence boundaries.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["Independent clauses need a real boundary","Colons and introductory material","Direct speech","Apostrophes and capitals"],"rules":[{"title":"Independent clauses need a real boundary","explanation":"A comma alone does not normally join two independent clauses in formal prose. Use a full stop, a semicolon, or a comma with a suitable coordinating conjunction. A semicolon joins closely related main clauses without a conjunction.","pattern":"The train stopped**;** we got off.","commonMistakes":["The train stopped, we got off is a comma splice in ordinary formal writing."],"examples":["Choose punctuation that joins two main clauses without a conjunction: “We prepared the visitor guide **;** the supervisor thanked us.”","Choose punctuation that joins two main clauses without a conjunction: “We restored the old portrait **;** the supervisor thanked us.”"],"skill":"form"},{"title":"Colons and introductory material","explanation":"A colon can introduce an explanation or list after a complete clause. A comma commonly follows an introductory subordinate clause or a long introductory adverbial. A dash can mark a break or inserted explanation, with conventions varying by style.","pattern":"We need three things**:** paper, ink and time.","commonMistakes":["Do not routinely put a colon between a verb and its object: We need: paper is usually unnecessary punctuation."],"examples":["Where should the comma go in “After we prepared the visitor guide we rested”? → **After we prepared the visitor guide, we rested.**","Where should the comma go in “After we restored the old portrait we rested”? → **After we restored the old portrait, we rested.**"],"skill":"meaning"},{"title":"Direct speech","explanation":"Quotation marks show exact spoken or written words. A reporting clause can introduce the quotation with a comma. Capitalise the beginning of a full quoted sentence. Single versus double quotation marks and some punctuation placement vary by house style.","pattern":"She said, **“Please wait.”**","commonMistakes":["Reported speech normally removes quotation marks because it does not claim the same exact wording."],"examples":["Choose a correctly introduced direct instruction to prepare the visitor guide. → **She said, “Prepare the visitor guide.”**","Choose a correctly introduced direct instruction to restore the old portrait. → **She said, “Restore the old portrait.”**"],"skill":"contrast"},{"title":"Apostrophes and capitals","explanation":"Use apostrophes for contractions and possession, not ordinary plurals. Its is possessive; it’s means it is or it has. Capitalise sentence openings, the pronoun I and proper names, including languages and weekdays.","pattern":"**It’s** Tuesday. / The dog lost **its** collar.","commonMistakes":["Quotation style varies, but the distinction between its and it’s is grammatical rather than an optional style choice."],"examples":["“**It’s** time to prepare the visitor guide.” Choose the contraction meaning “it is”.","“**It’s** time to restore the old portrait.” Choose the contraction meaning “it is”."],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["dfe-grammar"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"quizItems":[{"id":"1fbcdb99-a565-5a48-a756-43edb18de6b2","topicSlug":"punctuation-clauses","level":"B1","prompt":"Choose punctuation that joins two main clauses without a conjunction: “We prepared the visitor guide ____ the supervisor thanked us.”","choices":[{"id":"A","text":"no punctuation"},{"id":"B","text":";"},{"id":"C","text":","},{"id":"D","text":"—,"}],"answerId":"B","hint":"Both sides can stand as sentences; use a **semicolon** when joining them without a conjunction.","explanation":"A **semicolon** can connect these related independent clauses.","keywords":["semicolon-main-clauses"],"skill":"semicolon-main-clauses","contextKey":"punctuation-clauses-1","fingerprint":"3c996cab81c81c6118a569b4eeb708a07a7e0bbe1a1c26702e49bb6c659e01d1","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["dfe-grammar"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Both sides can stand as sentences; use a **semicolon** when joining them without a conjunction.","A **semicolon** can connect these related independent clauses.","Choose **;**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The two independent clauses would run together.","B":"A **semicolon** can connect these related independent clauses.","C":"A comma alone would create a comma splice in formal prose.","D":"A dash-comma combination is not the standard boundary required here."}}},{"id":"fd726652-8936-57d0-a75a-677578299389","topicSlug":"punctuation-clauses","level":"B1","prompt":"Where should the comma go in “After we prepared the visitor guide we rested”?","choices":[{"id":"A","text":"After, we prepared the visitor guide we rested."},{"id":"B","text":"After we, prepared the visitor guide we rested."},{"id":"C","text":"After we prepared, the visitor guide we rested."},{"id":"D","text":"After we prepared the visitor guide, we rested."}],"answerId":"D","hint":"Find where the **introductory after-clause ends**.","explanation":"The comma separates the introductory after-clause from the main clause we rested.","keywords":["introductory-clause-comma"],"skill":"introductory-clause-comma","contextKey":"punctuation-clauses-1","fingerprint":"a8c88202dafcf01a9492330757c89cbfcf686f4d09907349e22da742d9694c85","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["dfe-grammar"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Find where the **introductory after-clause ends**.","The comma separates the introductory after-clause from the main clause we rested.","Choose **After we prepared the visitor guide, we rested.**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"This separates the subordinating word from its clause instead of marking the clause boundary.","B":"This separates the subject from its verb.","C":"This separates the transitive verb from its object.","D":"The comma separates the introductory after-clause from the main clause we rested."}}},{"id":"5e33f4c0-4a9a-543a-adb7-88b111a0233d","topicSlug":"punctuation-clauses","level":"B1","prompt":"Choose a correctly introduced direct instruction to prepare the visitor guide.","choices":[{"id":"A","text":"She said, prepare the visitor guide”."},{"id":"B","text":"She said, “Prepare the visitor guide.”"},{"id":"C","text":"She said “prepare the visitor guide”"},{"id":"D","text":"She, said “prepare the visitor guide.”"}],"answerId":"B","hint":"Check the **reporting clause, opening quotation mark, capital and closing punctuation**.","explanation":"A comma introduces the full quoted sentence, which begins with a capital and ends with punctuation.","keywords":["direct-speech-capital"],"skill":"direct-speech-capital","contextKey":"punctuation-clauses-1","fingerprint":"d16adb93035bd9586ed2e89773332cd323b8b2e7baeb8a7c51ee57da03921ddb","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["dfe-grammar"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Check the **reporting clause, opening quotation mark, capital and closing punctuation**.","A comma introduces the full quoted sentence, which begins with a capital and ends with punctuation.","Choose **She said, “Prepare the visitor guide.”**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The opening quotation mark is missing.","B":"A comma introduces the full quoted sentence, which begins with a capital and ends with punctuation.","C":"This version lacks the capital for the full quoted sentence and final punctuation.","D":"The comma wrongly separates the subject and verb, and the full quotation starts lowercase."}}},{"id":"faf22390-aa1c-57ad-aed3-145fb41c7620","topicSlug":"punctuation-clauses","level":"B1","prompt":"“____ time to prepare the visitor guide.” Choose the contraction meaning “it is”.","choices":[{"id":"A","text":"I’ts"},{"id":"B","text":"It’s"},{"id":"C","text":"Its"},{"id":"D","text":"Its’"}],"answerId":"B","hint":"Expand the word: the sentence needs **it is**.","explanation":"**It’s** contracts **it is** in this sentence.","keywords":["its-contraction"],"skill":"its-contraction","contextKey":"punctuation-clauses-1","fingerprint":"2c7a6bb7967600a1539eec99232f6b97e1db3692e28fcf675dff9c86861774c7","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["dfe-grammar"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Expand the word: the sentence needs **it is**.","**It’s** contracts **it is** in this sentence.","Choose **It’s**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The apostrophe is misplaced; it replaces the missing letter in is.","B":"**It’s** contracts **it is** in this sentence.","C":"Its is a possessive determiner, not the requested contraction.","D":"Its’ is not the standard contraction or possessive form."}}},{"id":"ccb05e34-79e0-5ba9-a376-b12d6cac7730","topicSlug":"punctuation-clauses","level":"B1","prompt":"Choose punctuation that joins two main clauses without a conjunction: “We restored the old portrait ____ the supervisor thanked us.”","choices":[{"id":"A","text":","},{"id":"B","text":"—,"},{"id":"C","text":"no punctuation"},{"id":"D","text":";"}],"answerId":"D","hint":"Both sides can stand as sentences; use a **semicolon** when joining them without a conjunction.","explanation":"A **semicolon** can connect these related independent clauses.","keywords":["semicolon-main-clauses"],"skill":"semicolon-main-clauses","contextKey":"punctuation-clauses-2","fingerprint":"5a4138d11075996fc763aa5ec174318ee79ca2ab5bcafbdbc86f60286eed2e89","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["dfe-grammar"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Both sides can stand as sentences; use a **semicolon** when joining them without a conjunction.","A **semicolon** can connect these related independent clauses.","Choose **;**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"A comma alone would create a comma splice in formal prose.","B":"A dash-comma combination is not the standard boundary required here.","C":"The two independent clauses would run together.","D":"A **semicolon** can connect these related independent clauses."}}},{"id":"373c1125-06e5-5e15-ac91-47e460834fd0","topicSlug":"punctuation-clauses","level":"B1","prompt":"Where should the comma go in “After we restored the old portrait we rested”?","choices":[{"id":"A","text":"After we, restored the old portrait we rested."},{"id":"B","text":"After we restored, the old portrait we rested."},{"id":"C","text":"After we restored the old portrait, we rested."},{"id":"D","text":"After, we restored the old portrait we rested."}],"answerId":"C","hint":"Find where the **introductory after-clause ends**.","explanation":"The comma separates the introductory after-clause from the main clause we rested.","keywords":["introductory-clause-comma"],"skill":"introductory-clause-comma","contextKey":"punctuation-clauses-2","fingerprint":"a28fa81347b8dc411fc3ab83a8ca8af61b957674bc5cc9190ddf3cfcee11eaca","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["dfe-grammar"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Find where the **introductory after-clause ends**.","The comma separates the introductory after-clause from the main clause we rested.","Choose **After we restored the old portrait, we rested.**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"This separates the subject from its verb.","B":"This separates the transitive verb from its object.","C":"The comma separates the introductory after-clause from the main clause we rested.","D":"This separates the subordinating word from its clause instead of marking the clause boundary."}}},{"id":"1f359de5-1d46-5b23-a5c6-1f9c762e226e","topicSlug":"punctuation-clauses","level":"B1","prompt":"Choose a correctly introduced direct instruction to restore the old portrait.","choices":[{"id":"A","text":"She said, restore the old portrait”."},{"id":"B","text":"She said, “Restore the old portrait.”"},{"id":"C","text":"She said “restore the old portrait”"},{"id":"D","text":"She, said “restore the old portrait.”"}],"answerId":"B","hint":"Check the **reporting clause, opening quotation mark, capital and closing punctuation**.","explanation":"A comma introduces the full quoted sentence, which begins with a capital and ends with punctuation.","keywords":["direct-speech-capital"],"skill":"direct-speech-capital","contextKey":"punctuation-clauses-2","fingerprint":"6e35954d451c704ebdf36eff81bce18d6fe73ed4760947f0f556c2f6e82b544f","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["dfe-grammar"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Check the **reporting clause, opening quotation mark, capital and closing punctuation**.","A comma introduces the full quoted sentence, which begins with a capital and ends with punctuation.","Choose **She said, “Restore the old portrait.”**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The opening quotation mark is missing.","B":"A comma introduces the full quoted sentence, which begins with a capital and ends with punctuation.","C":"This version lacks the capital for the full quoted sentence and final punctuation.","D":"The comma wrongly separates the subject and verb, and the full quotation starts lowercase."}}},{"id":"b0be10d9-8033-5b1e-a156-ecc20162e51d","topicSlug":"punctuation-clauses","level":"B1","prompt":"“____ time to restore the old portrait.” Choose the contraction meaning “it is”.","choices":[{"id":"A","text":"Its’"},{"id":"B","text":"I’ts"},{"id":"C","text":"It’s"},{"id":"D","text":"Its"}],"answerId":"C","hint":"Expand the word: the sentence needs **it is**.","explanation":"**It’s** contracts **it is** in this sentence.","keywords":["its-contraction"],"skill":"its-contraction","contextKey":"punctuation-clauses-2","fingerprint":"602ed2d8396dffe43e234f5250e24d6189849d08250affb7e5598d95248041b0","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["dfe-grammar"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Expand the word: the sentence needs **it is**.","**It’s** contracts **it is** in this sentence.","Choose **It’s**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Its’ is not the standard contraction or possessive form.","B":"The apostrophe is misplaced; it replaces the missing letter in is.","C":"**It’s** contracts **it is** in this sentence.","D":"Its is a possessive determiner, not the requested contraction."}}},{"id":"9f1cdb60-8010-5566-ae1c-215173c13411","topicSlug":"punctuation-clauses","level":"B1","prompt":"Choose punctuation that joins two main clauses without a conjunction: “We measured the garden fence ____ the supervisor thanked us.”","choices":[{"id":"A","text":","},{"id":"B","text":"—,"},{"id":"C","text":"no punctuation"},{"id":"D","text":";"}],"answerId":"D","hint":"Both sides can stand as sentences; use a **semicolon** when joining them without a conjunction.","explanation":"A **semicolon** can connect these related independent clauses.","keywords":["semicolon-main-clauses"],"skill":"semicolon-main-clauses","contextKey":"punctuation-clauses-3","fingerprint":"078ac5b2f93d18c23e332befacab5283e20731325144de13aabf7c131431ab25","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["dfe-grammar"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Both sides can stand as sentences; use a **semicolon** when joining them without a conjunction.","A **semicolon** can connect these related independent clauses.","Choose **;**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"A comma alone would create a comma splice in formal prose.","B":"A dash-comma combination is not the standard boundary required here.","C":"The two independent clauses would run together.","D":"A **semicolon** can connect these related independent clauses."}}},{"id":"0db2aea0-9d22-5add-a6b2-6b5ceb8f81d8","topicSlug":"punctuation-clauses","level":"B1","prompt":"Where should the comma go in “After we measured the garden fence we rested”?","choices":[{"id":"A","text":"After we, measured the garden fence we rested."},{"id":"B","text":"After we measured, the garden fence we rested."},{"id":"C","text":"After we measured the garden fence, we rested."},{"id":"D","text":"After, we measured the garden fence we rested."}],"answerId":"C","hint":"Find where the **introductory after-clause ends**.","explanation":"The comma separates the introductory after-clause from the main clause we rested.","keywords":["introductory-clause-comma"],"skill":"introductory-clause-comma","contextKey":"punctuation-clauses-3","fingerprint":"0e4b82a63d82babe605473d484f2461cfe39baa3d62ed200a90168880ed37203","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["dfe-grammar"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Find where the **introductory after-clause ends**.","The comma separates the introductory after-clause from the main clause we rested.","Choose **After we measured the garden fence, we rested.**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"This separates the subject from its verb.","B":"This separates the transitive verb from its object.","C":"The comma separates the introductory after-clause from the main clause we rested.","D":"This separates the subordinating word from its clause instead of marking the clause boundary."}}},{"id":"d5704afe-4d87-534b-ae7a-f5e3d7785553","topicSlug":"punctuation-clauses","level":"B1","prompt":"Choose a correctly introduced direct instruction to measure the garden fence.","choices":[{"id":"A","text":"She said “measure the garden fence”"},{"id":"B","text":"She, said “measure the garden fence.”"},{"id":"C","text":"She said, measure the garden fence”."},{"id":"D","text":"She said, “Measure the garden fence.”"}],"answerId":"D","hint":"Check the **reporting clause, opening quotation mark, capital and closing punctuation**.","explanation":"A comma introduces the full quoted sentence, which begins with a capital and ends with punctuation.","keywords":["direct-speech-capital"],"skill":"direct-speech-capital","contextKey":"punctuation-clauses-3","fingerprint":"a3d131f601b8b839f51db72dd3141d6ad0457c7325b215f3a5e9ef315bffb7c1","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["dfe-grammar"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Check the **reporting clause, opening quotation mark, capital and closing punctuation**.","A comma introduces the full quoted sentence, which begins with a capital and ends with punctuation.","Choose **She said, “Measure the garden fence.”**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"This version lacks the capital for the full quoted sentence and final punctuation.","B":"The comma wrongly separates the subject and verb, and the full quotation starts lowercase.","C":"The opening quotation mark is missing.","D":"A comma introduces the full quoted sentence, which begins with a capital and ends with punctuation."}}},{"id":"1f2a49c8-70b0-5900-a092-d9b03b14bb4c","topicSlug":"punctuation-clauses","level":"B1","prompt":"“____ time to measure the garden fence.” Choose the contraction meaning “it is”.","choices":[{"id":"A","text":"It’s"},{"id":"B","text":"Its"},{"id":"C","text":"Its’"},{"id":"D","text":"I’ts"}],"answerId":"A","hint":"Expand the word: the sentence needs **it is**.","explanation":"**It’s** contracts **it is** in this sentence.","keywords":["its-contraction"],"skill":"its-contraction","contextKey":"punctuation-clauses-3","fingerprint":"110cec16fa9999340055fe556d0bef63b341f03f52daf9f1e917ad1b9fd3a380","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["dfe-grammar"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Expand the word: the sentence needs **it is**.","**It’s** contracts **it is** in this sentence.","Choose **It’s**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"**It’s** contracts **it is** in this sentence.","B":"Its is a possessive determiner, not the requested contraction.","C":"Its’ is not the standard contraction or possessive form.","D":"The apostrophe is misplaced; it replaces the missing letter in is."}}},{"id":"548eb910-4478-55f7-ae93-433061863853","topicSlug":"punctuation-clauses","level":"B1","prompt":"Choose punctuation that joins two main clauses without a conjunction: “We translated the travel leaflet ____ the supervisor thanked us.”","choices":[{"id":"A","text":"—,"},{"id":"B","text":"no punctuation"},{"id":"C","text":";"},{"id":"D","text":","}],"answerId":"C","hint":"Both sides can stand as sentences; use a **semicolon** when joining them without a conjunction.","explanation":"A **semicolon** can connect these related independent clauses.","keywords":["semicolon-main-clauses"],"skill":"semicolon-main-clauses","contextKey":"punctuation-clauses-4","fingerprint":"2c63fda3dc12bf41267973c818964956908bb230b39cc45a6fa239e3aa3e1876","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["dfe-grammar"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Both sides can stand as sentences; use a **semicolon** when joining them without a conjunction.","A **semicolon** can connect these related independent clauses.","Choose **;**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"A dash-comma combination is not the standard boundary required here.","B":"The two independent clauses would run together.","C":"A **semicolon** can connect these related independent clauses.","D":"A comma alone would create a comma splice in formal prose."}}},{"id":"63f8e9ea-daf9-5b7e-acd3-a9b73494b9d7","topicSlug":"punctuation-clauses","level":"B1","prompt":"Where should the comma go in “After we translated the travel leaflet we rested”?","ch